// Auto-extracted from index.html to keep the main shell maintainable.
// Injected before Alpine initializes, so existing bindings and handlers remain unchanged.
(() => {
  const html = "          <div x-show=\"page==='myWork'\" x-cloak>\r\n            <template x-if=\"myWork\">\r\n              <div>\r\n                <!-- Decision cockpit -->\r\n                <div class=\"bg-white border border-slate-200 rounded-2xl p-5 mb-4 shadow-sm\">\r\n                  <div class=\"flex justify-between items-center flex-wrap gap-4\">\r\n                    <div>\r\n                      <div class=\"text-sm text-emerald-700 font-semibold flex items-center gap-2\">\r\n                        <span>مركز القرار اليومي</span>\r\n                        <span class=\"text-[10px] rounded-full bg-emerald-50 border border-emerald-100 text-emerald-700 px-2 py-0.5\" x-text=\"myWorkRoleFocus().title\"></span>\r\n                      </div>\r\n                      <h2 class=\"text-2xl font-bold mt-1 text-slate-900\" x-text=\"myWorkRolePageTitle()\"></h2>\r\n                      <div class=\"text-xs text-slate-500 mt-1\">القاعدة: عالج أول بطاقة، ثم انتقل لما بعدها. التفاصيل محفوظة لكنها ليست أمامك طوال الوقت.</div>\r\n                    </div>\r\n                    <div class=\"grid grid-cols-4 gap-2 text-center text-xs min-w-[320px]\">\r\n                      <div class=\"rounded-xl bg-slate-50 border px-3 py-2\">\r\n                        <div class=\"text-lg font-bold text-slate-800\" x-text=\"myWorkComfortStats().total\"></div>\r\n                        <div class=\"text-slate-500\">إجمالي</div>\r\n                      </div>\r\n                      <div class=\"rounded-xl bg-rose-50 border border-rose-100 px-3 py-2\">\r\n                        <div class=\"text-lg font-bold text-rose-700\" x-text=\"myWorkComfortStats().urgent\"></div>\r\n                        <div class=\"text-rose-600\">عاجل</div>\r\n                      </div>\r\n                      <div class=\"rounded-xl bg-amber-50 border border-amber-100 px-3 py-2\">\r\n                        <div class=\"text-lg font-bold text-amber-700\" x-text=\"myWorkComfortStats().follow\"></div>\r\n                        <div class=\"text-amber-700\">متابعة</div>\r\n                      </div>\r\n                      <div class=\"rounded-xl bg-sky-50 border border-sky-100 px-3 py-2\">\r\n                        <div class=\"text-lg font-bold text-sky-700\" x-text=\"myWorkComfortStats().info\"></div>\r\n                        <div class=\"text-sky-700\">معلومة</div>\r\n                      </div>\r\n                    </div>\r\n                  </div>\r\n                  <div class=\"mt-4 rounded-xl border px-4 py-3 text-sm font-semibold\"\r\n                       :class=\"myWorkStatusClass()\"\r\n                       x-text=\"myWorkStatusText()\"></div>\r\n                </div>\r\n\r\n                <div class=\"bg-white border border-emerald-100 rounded-2xl p-4 mb-4 shadow-sm\">\r\n                  <div class=\"flex items-center justify-between gap-3 flex-wrap mb-3\">\r\n                    <div>\r\n                      <div class=\"text-[11px] font-bold text-emerald-700\">مسار الإنجاز السريع</div>\r\n                      <div class=\"text-xs text-slate-500 mt-0.5\">ادخل، أنجز المطلوب، ثم ارجع لهذه الصفحة للتأكد أن العدد نقص.</div>\r\n                    </div>\r\n                    <button @click=\"loadMyWork()\" class=\"text-xs border border-emerald-200 text-emerald-700 rounded-lg px-3 py-1 hover:bg-emerald-50\">تحديث الحالة</button>\r\n                  </div>\r\n                  <div class=\"grid md:grid-cols-3 gap-2\">\r\n                    <template x-for=\"step in myWorkRoleFocus().steps\" :key=\"step[0]\">\r\n                      <div class=\"rounded-xl bg-slate-50 border border-slate-100 px-3 py-3 flex items-start gap-3\">\r\n                        <div class=\"w-7 h-7 rounded-full bg-emerald-600 text-white flex items-center justify-center text-xs font-bold shrink-0\" x-text=\"step[0]\"></div>\r\n                        <div>\r\n                          <div class=\"text-sm font-bold text-slate-800\" x-text=\"step[1]\"></div>\r\n                          <div class=\"text-[11px] text-slate-500 mt-1\">خطوة واحدة تكفي. لا تحتاج فتح كل النظام.</div>\r\n                        </div>\r\n                      </div>\r\n                    </template>\r\n                  </div>\r\n                </div>\r\n\r\n                <div class=\"bg-gradient-to-l from-emerald-50 to-white border border-emerald-100 rounded-2xl p-5 mb-4 shadow-sm\">\r\n                  <div class=\"flex items-center justify-between gap-4\">\r\n                    <div class=\"min-w-0\">\r\n                      <div class=\"text-[11px] font-bold text-emerald-700 mb-1\">الإجراء التالي</div>\r\n                      <div class=\"flex items-center gap-2\">\r\n                        <span class=\"text-lg\" x-text=\"myWorkDecisionLead().icon\"></span>\r\n                        <h3 class=\"font-bold text-slate-900 text-lg truncate\" x-text=\"myWorkDecisionLead().title\"></h3>\r\n                        <span class=\"text-[10px] rounded-full bg-white border px-2 py-0.5 text-slate-600\" x-text=\"myWorkSeverityLabel(myWorkDecisionLead().severity)\"></span>\r\n                      </div>\r\n                      <p class=\"text-xs text-slate-600 mt-1\" x-text=\"myWorkDecisionLead().reason\"></p>\r\n                      <p class=\"text-[11px] text-slate-500 mt-2\">\r\n                        <span class=\"font-bold\">سبب الظهور:</span>\r\n                        <span x-text=\"myWorkDecisionLead().source\"></span>\r\n                      </p>\r\n                    </div>\r\n                    <button x-show=\"myWorkDecisionLead().page\"\r\n                            @click=\"myWorkDecisionAction(myWorkDecisionLead())\"\r\n                            class=\"shrink-0 text-xs bg-emerald-700 hover:bg-emerald-800 text-white rounded-lg px-4 py-2 font-semibold\">\r\n                      فتح الإجراء ←\r\n                    </button>\r\n                  </div>\r\n                </div>\r\n\r\n                <!-- Quick Actions — kept folded so the dashboard stays decision-first -->\r\n                <template x-if=\"quickActions().length\">\r\n                  <details class=\"bg-white border rounded-xl mb-4 overflow-hidden\">\r\n                    <summary class=\"cursor-pointer px-4 py-3 text-sm font-bold text-slate-700 bg-slate-50 hover:bg-slate-100 list-none flex items-center justify-between\">\r\n                      <span>إجراءات سريعة</span>\r\n                      <span class=\"text-[11px] text-slate-500 font-normal\">اختصارات عند الحاجة فقط</span>\r\n                    </summary>\r\n                    <div class=\"grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-2 p-3\">\r\n                      <template x-for=\"a in quickActions()\" :key=\"a.id\">\r\n                        <button @click=\"trackQuickAction(a.id); a.onClick()\"\r\n                                :class=\"{\r\n                                  'bg-rose-50 hover:bg-rose-100 border-rose-200 text-rose-800':         a.color==='rose',\r\n                                  'bg-orange-50 hover:bg-orange-100 border-orange-200 text-orange-800': a.color==='orange',\r\n                                  'bg-amber-50 hover:bg-amber-100 border-amber-200 text-amber-800':     a.color==='amber',\r\n                                  'bg-indigo-50 hover:bg-indigo-100 border-indigo-200 text-indigo-800': a.color==='indigo',\r\n                                  'bg-violet-50 hover:bg-violet-100 border-violet-200 text-violet-800': a.color==='violet',\r\n                                  'ring-2 ring-offset-1 ring-yellow-400': a.mostUsed\r\n                                }\"\r\n                                class=\"relative flex items-center gap-2 p-3 rounded-lg border transition text-right\">\r\n                          <span class=\"text-xl\" x-text=\"a.icon\"></span>\r\n                          <div class=\"flex-1 min-w-0\">\r\n                            <div class=\"text-sm font-bold\" x-text=\"a.label\"></div>\r\n                            <div class=\"text-[10px] opacity-75\" x-text=\"a.sublabel\"></div>\r\n                          </div>\r\n                          <template x-if=\"a.mostUsed\">\r\n                            <span class=\"absolute -top-2 -left-2 bg-yellow-400 text-yellow-900 text-[9px] font-bold rounded-full px-1.5 py-0.5 shadow\"\r\n                                  title=\"أكثر ما تستخدمه\">⭐ الأكثر</span>\r\n                          </template>\r\n                        </button>\r\n                      </template>\r\n                    </div>\r\n                  </details>\r\n                </template>\r\n\r\n                <div class=\"grid lg:grid-cols-3 gap-3 mb-4\">\r\n                  <div class=\"lg:col-span-2 bg-white border rounded-xl p-4\">\r\n                    <div class=\"flex items-center justify-between mb-3\">\r\n                      <div>\r\n                        <div class=\"font-bold text-gray-800 text-sm\">أولوية العمل الآن</div>\r\n                        <div class=\"text-[11px] text-gray-500\" x-text=\"myWorkPriorityCaption()\"></div>\r\n                      </div>\r\n                      <button @click=\"loadMyWork()\" class=\"text-xs border rounded-lg px-3 py-1 hover:bg-gray-50\">تحديث</button>\r\n                    </div>\r\n                    <div class=\"space-y-2\">\r\n                      <template x-for=\"item in myWorkDecisionItems()\" :key=\"item.id || (item.title + item.page)\">\r\n                        <div class=\"flex items-start justify-between gap-3 rounded-xl border px-3 py-2.5 shadow-sm\"\r\n                             :class=\"myWorkDecisionToneClass(item.severity)\">\r\n                          <div class=\"min-w-0 flex-1\">\r\n                            <div class=\"flex items-center gap-2 min-w-0\">\r\n                              <span class=\"text-base shrink-0\" x-text=\"item.icon\"></span>\r\n                              <div class=\"text-sm font-semibold min-w-0 truncate\" x-text=\"item.title\"></div>\r\n                              <span class=\"text-[10px] bg-slate-50 border rounded-full px-2 py-0.5 shrink-0 text-slate-500\" x-text=\"myWorkSeverityLabel(item.severity)\"></span>\r\n                              <span x-show=\"item.count\" class=\"text-[10px] bg-white/80 border rounded-full px-2 py-0.5 shrink-0\" x-text=\"item.count\"></span>\r\n                            </div>\r\n                            <div class=\"text-[11px] opacity-75 mt-1 line-clamp-2\" x-text=\"item.reason\"></div>\r\n                            <div class=\"text-[10px] text-slate-500 mt-1\">\r\n                              <span class=\"font-bold\">سبب الظهور:</span>\r\n                              <span x-text=\"item.source\"></span>\r\n                            </div>\r\n                          </div>\r\n                          <button x-show=\"item.page\" @click=\"myWorkDecisionAction(item)\"\r\n                                  class=\"text-xs bg-white border rounded-lg px-3 py-1 hover:bg-gray-50 whitespace-nowrap\"\r\n                                  x-text=\"item.label + ' ←'\"></button>\r\n                        </div>\r\n                      </template>\r\n                      <div x-show=\"!myWorkDecisionItems().length\" class=\"rounded-lg border border-emerald-100 bg-emerald-50 text-emerald-800 px-3 py-2 text-sm\">\r\n                        لا يوجد إجراء عاجل الآن. ركّز على إدخال القراءات الدورية فقط.\r\n                      </div>\r\n                    </div>\r\n                  </div>\r\n\r\n                  <div class=\"bg-white border rounded-xl p-4\">\r\n                    <div class=\"flex items-center justify-between mb-3\">\r\n                      <div class=\"font-bold text-gray-800 text-sm\">متابعات مفتوحة</div>\r\n                      <span class=\"text-xs rounded-full bg-slate-100 text-slate-700 px-2 py-0.5\" x-text=\"myWorkFollowUpBuckets().total\"></span>\r\n                    </div>\r\n                    <div class=\"space-y-2 text-xs\">\r\n                      <div class=\"rounded-lg border p-2 bg-white border-slate-200 text-slate-700\">\r\n                        <b x-text=\"myWorkFollowUpBuckets().overdue.length\"></b>\r\n                        <span> متأخرة — ابدأ بالأقدم فقط</span>\r\n                      </div>\r\n                      <div class=\"rounded-lg border p-2 bg-slate-50 text-slate-700\">\r\n                        <b x-text=\"myWorkFollowUpBuckets().open.length\"></b>\r\n                        <span> مهمة مفتوحة ضمن نطاقك</span>\r\n                      </div>\r\n                      <button @click=\"goToResource('follow-up-tasks')\" class=\"w-full border rounded-lg py-2 hover:bg-gray-50 text-gray-700 font-semibold\">فتح سجل المتابعة</button>\r\n                    </div>\r\n                  </div>\r\n                </div>\r\n\r\n                <!-- Alerts details — مطوية لتقليل الضجيج البصري -->\r\n                <details x-show=\"(myWork.alerts||[]).length\" class=\"bg-white border rounded-xl mb-4 overflow-hidden\">\r\n                  <summary class=\"cursor-pointer px-4 py-3 text-sm font-bold text-slate-700 bg-slate-50 hover:bg-slate-100\">\r\n                    كل التنبيهات التفصيلية\r\n                    <span class=\"text-[11px] bg-white border rounded-full px-2 py-0.5 mr-2\" x-text=\"(myWork.alerts||[]).length\"></span>\r\n                  </summary>\r\n                  <div class=\"space-y-2 p-3\">\r\n                    <template x-for=\"a in (myWork.alerts||[])\" :key=\"a.type\">\r\n                      <div class=\"flex items-center justify-between gap-3 rounded-lg border px-4 py-3 bg-white\"\r\n                           :class=\"{\r\n                             'border-r-4 border-r-rose-500': a.severity==='critical',\r\n                             'border-r-4 border-r-amber-400': a.severity==='warning',\r\n                             'border-r-4 border-r-sky-400': a.severity==='info'\r\n                           }\">\r\n                        <div class=\"flex items-center gap-3 min-w-0\">\r\n                          <span class=\"text-base flex-shrink-0\"\r\n                                x-text=\"a.severity==='critical' ? '⛔' : (a.severity==='warning' ? '⚠' : 'ℹ')\"></span>\r\n                          <div class=\"font-medium text-sm truncate text-slate-800\" x-text=\"a.title\"></div>\r\n                        </div>\r\n                        <button @click=\"goToResource(a.action.page)\"\r\n                                class=\"text-xs bg-white border hover:bg-gray-50 rounded px-3 py-1.5 font-medium whitespace-nowrap\"\r\n                                x-text=\"(a.action?.label || 'فتح') + ' ←'\"></button>\r\n                      </div>\r\n                    </template>\r\n                  </div>\r\n                </details>\r\n\r\n                <!-- Pending Acks — إقرارات بانتظار توقيعك -->\r\n                <template x-if=\"(myWork.pendingAcks||[]).length || (myWork.pendingAckDocuments||[]).length\">\r\n                  <div class=\"bg-white border rounded-xl p-4 mb-4\">\r\n                    <div class=\"flex items-center justify-between mb-3\">\r\n                      <div class=\"font-bold text-teal-800 text-sm\">📋 إقرارات بانتظار توقيعك\r\n                        <span class=\"ml-1 text-[11px] bg-teal-100 text-teal-700 rounded-full px-2 py-0.5\" x-text=\"(myWork.pendingAcks||[]).length + (myWork.pendingAckDocuments||[]).length\"></span>\r\n                      </div>\r\n                      <button @click=\"goToResource('myAcknowledgments')\" class=\"text-xs text-teal-600 hover:underline\">كل الإقرارات ←</button>\r\n                    </div>\r\n                    <ul class=\"divide-y text-sm border rounded\">\r\n                      <template x-for=\"d in (myWork.pendingAckDocuments||[]).slice(0,5)\" :key=\"'doc-' + d.id\">\r\n                        <li class=\"p-2 flex justify-between items-center gap-2 hover:bg-gray-50\">\r\n                          <div class=\"flex-1 min-w-0\">\r\n                            <span class=\"font-mono text-xs text-gray-500 ml-2\" x-text=\"d.code\"></span>\r\n                            <span class=\"truncate\" x-text=\"d.title\"></span>\r\n                          </div>\r\n                          <button @click=\"goToResource('myAcknowledgments')\"\r\n                                  class=\"text-xs bg-teal-600 text-white hover:bg-teal-700 rounded px-3 py-1\">راجع وأقر ←</button>\r\n                        </li>\r\n                      </template>\r\n                      <template x-for=\"t in myWork.pendingAcks.slice(0,5)\" :key=\"t.id\">\r\n                        <li class=\"p-2 flex justify-between items-center gap-2 hover:bg-gray-50\">\r\n                          <div class=\"flex-1 min-w-0\">\r\n                            <span class=\"font-mono text-xs text-gray-500 ml-2\" x-text=\"t.document?.code\"></span>\r\n                            <span class=\"truncate\" x-text=\"t.document?.title\"></span>\r\n                          </div>\r\n                          <a :href=\"'/ack/' + t.token\" target=\"_blank\"\r\n                             class=\"text-xs bg-teal-600 text-white hover:bg-teal-700 rounded px-3 py-1\">وقّع الآن ←</a>\r\n                        </li>\r\n                      </template>\r\n                    </ul>\r\n                  </div>\r\n                </template>\r\n\r\n                <!-- Pending performance reviews — تقييمات أداء بانتظار تعليق الموظف -->\r\n                <template x-if=\"(myWork.pendingPerformanceReviews||[]).length\">\r\n                  <div class=\"bg-white border rounded-xl p-4 mb-4\">\r\n                    <div class=\"flex items-center justify-between mb-3\">\r\n                      <div class=\"font-bold text-indigo-800 text-sm\">⭐ تقييمات أداء بانتظار تعليقك وتوقيعك\r\n                        <span class=\"ml-1 text-[11px] bg-indigo-100 text-indigo-700 rounded-full px-2 py-0.5\" x-text=\"myWork.pendingPerformanceReviews.length\"></span>\r\n                      </div>\r\n                      <div class=\"text-[11px] text-gray-500\">راجع الملخص ثم أضف تعليقك. التوقيع يعني الاطلاع وليس بالضرورة الاعتراض أو الموافقة الكاملة.</div>\r\n                    </div>\r\n                    <div class=\"space-y-2\">\r\n                      <template x-for=\"r in myWork.pendingPerformanceReviews.slice(0,5)\" :key=\"r.id\">\r\n                        <div class=\"border rounded-lg p-3 bg-indigo-50/40\">\r\n                          <div class=\"flex flex-wrap items-center justify-between gap-2\">\r\n                            <div>\r\n                              <div class=\"font-bold text-sm text-slate-900\">\r\n                                <span class=\"font-mono text-xs text-gray-500 ml-2\" x-text=\"r.code\"></span>\r\n                                <span x-text=\"'الفترة: ' + r.period\"></span>\r\n                              </div>\r\n                              <div class=\"text-xs text-gray-500 mt-1\">\r\n                                المقيم: <span x-text=\"r.reviewer?.name || '—'\"></span>\r\n                                · التقدير: <b x-text=\"r.grade || '—'\"></b>\r\n                                · المتوسط: <b x-text=\"r.overallRating ? Number(r.overallRating).toFixed(1) : '—'\"></b>\r\n                              </div>\r\n                            </div>\r\n                            <button @click=\"perfReviewSign(r)\"\r\n                                    class=\"text-xs bg-indigo-600 text-white hover:bg-indigo-700 rounded px-3 py-1.5\">تعليق وتوقيع</button>\r\n                          </div>\r\n                          <div class=\"grid md:grid-cols-2 gap-2 mt-3 text-xs\">\r\n                            <div class=\"bg-white border rounded p-2\">\r\n                              <div class=\"font-bold text-emerald-700 mb-1\">نقاط القوة</div>\r\n                              <div class=\"whitespace-pre-line text-gray-700\" x-text=\"r.strengths || '—'\"></div>\r\n                            </div>\r\n                            <div class=\"bg-white border rounded p-2\">\r\n                              <div class=\"font-bold text-amber-700 mb-1\">مجالات التحسين وخطة الدعم</div>\r\n                              <div class=\"whitespace-pre-line text-gray-700\" x-text=\"r.areasToImprove || r.developmentPlan || '—'\"></div>\r\n                            </div>\r\n                          </div>\r\n                        </div>\r\n                      </template>\r\n                    </div>\r\n                  </div>\r\n                </template>\r\n\r\n                <!-- My Drafts — مسوّداتي التي لم تُرسَل بعد -->\r\n                <template x-if=\"myWork.myDrafts && myWork.myDrafts.total > 0\">\r\n                  <div class=\"bg-white border rounded-xl p-4 mb-4\">\r\n                    <div class=\"flex items-center justify-between mb-3\">\r\n                      <div class=\"font-bold text-slate-800 text-sm\">📝 مسوّداتي\r\n                        <span class=\"ml-1 text-[11px] bg-slate-100 text-slate-700 rounded-full px-2 py-0.5\" x-text=\"myWork.myDrafts.total\"></span>\r\n                      </div>\r\n                      <div class=\"text-[11px] text-gray-500\">أكمِلها أو أرسلها للمراجعة</div>\r\n                    </div>\r\n                    <div class=\"grid grid-cols-1 md:grid-cols-3 gap-3\">\r\n                      <template x-if=\"(myWork.myDrafts.ncr||[]).length\">\r\n                        <div class=\"border rounded-lg p-2\">\r\n                          <div class=\"text-[11px] font-bold text-orange-700 mb-1\">⚠️ <span x-text=\"t('NCR')\"></span> (<span x-text=\"myWork.myDrafts.ncr.length\"></span>)</div>\r\n                          <ul class=\"text-xs divide-y\">\r\n                            <template x-for=\"d in myWork.myDrafts.ncr\" :key=\"d.id\">\r\n                              <li class=\"py-1 flex justify-between items-center gap-1 hover:bg-gray-50\">\r\n                                <div class=\"flex-1 min-w-0 flex items-center gap-1 cursor-pointer\" @click=\"goToResource('ncr')\">\r\n                                  <span class=\"font-mono text-gray-500 text-[10px]\" x-text=\"d.code\"></span>\r\n                                  <span class=\"flex-1 truncate mr-1\" x-text=\"d.title\"></span>\r\n                                </div>\r\n                                <button type=\"button\"\r\n                                        @click.stop=\"inboxSubmit(d, 'ncr')\"\r\n                                        :disabled=\"inboxBusy(d, 'submit')\"\r\n                                        class=\"text-[10px] bg-orange-600 hover:bg-orange-700 text-white rounded px-2 py-0.5 disabled:opacity-50 whitespace-nowrap\"\r\n                                        title=\"أرسل هذه المسوّدة للمراجعة بدون مغادرة هذه الصفحة\">📨 أرسِل</button>\r\n                              </li>\r\n                            </template>\r\n                          </ul>\r\n                        </div>\r\n                      </template>\r\n                      <template x-if=\"(myWork.myDrafts.risks||[]).length\">\r\n                        <div class=\"border rounded-lg p-2\">\r\n                          <div class=\"text-[11px] font-bold text-amber-700 mb-1\">🛡️ مخاطر (<span x-text=\"myWork.myDrafts.risks.length\"></span>)</div>\r\n                          <ul class=\"text-xs divide-y\">\r\n                            <template x-for=\"d in myWork.myDrafts.risks\" :key=\"d.id\">\r\n                              <li class=\"py-1 flex justify-between items-center gap-1 hover:bg-gray-50\">\r\n                                <div class=\"flex-1 min-w-0 flex items-center gap-1 cursor-pointer\" @click=\"goToResource('risks')\">\r\n                                  <span class=\"font-mono text-gray-500 text-[10px]\" x-text=\"d.code\"></span>\r\n                                  <span class=\"flex-1 truncate mr-1\" x-text=\"d.title\"></span>\r\n                                </div>\r\n                                <button type=\"button\"\r\n                                        @click.stop=\"inboxSubmit(d, 'risks')\"\r\n                                        :disabled=\"inboxBusy(d, 'submit')\"\r\n                                        class=\"text-[10px] bg-amber-600 hover:bg-amber-700 text-white rounded px-2 py-0.5 disabled:opacity-50 whitespace-nowrap\"\r\n                                        title=\"أرسل المخاطرة للمراجعة\">📨 أرسِل</button>\r\n                              </li>\r\n                            </template>\r\n                          </ul>\r\n                        </div>\r\n                      </template>\r\n                      <template x-if=\"(myWork.myDrafts.documents||[]).length\">\r\n                        <div class=\"border rounded-lg p-2\">\r\n                          <div class=\"text-[11px] font-bold text-sky-700 mb-1\">📄 وثائق (<span x-text=\"myWork.myDrafts.documents.length\"></span>)</div>\r\n                          <ul class=\"text-xs divide-y\">\r\n                            <template x-for=\"d in myWork.myDrafts.documents\" :key=\"d.id\">\r\n                              <li class=\"py-1 flex justify-between items-center gap-1 hover:bg-gray-50 cursor-pointer\" @click=\"goToResource('documents')\">\r\n                                <span class=\"font-mono text-gray-500 text-[10px]\" x-text=\"d.code\"></span>\r\n                                <span class=\"flex-1 truncate mr-1\" x-text=\"d.title\"></span>\r\n                              </li>\r\n                            </template>\r\n                          </ul>\r\n                        </div>\r\n                      </template>\r\n                    </div>\r\n                  </div>\r\n                </template>\r\n\r\n                <!-- ⚡ Inline Quick KPI Entry — سلسلة إدخال مباشرة تنعكس على الأهداف والخطة الاستراتيجية -->\r\n                <template x-if=\"(myDue.pending || []).length\">\r\n                  <div class=\"bg-white border-2 border-violet-200 rounded-xl p-4 mb-4\">\r\n                    <div class=\"flex items-center justify-between mb-3\">\r\n                      <div>\r\n                        <div class=\"font-bold text-violet-800 text-sm\">⚡ أدخِل قراءاتك الآن\r\n                          <span class=\"ml-1 text-[11px] bg-violet-100 text-violet-700 rounded-full px-2 py-0.5\"\r\n                                x-text=\"myDue.pending.length + ' معلّقة'\"></span>\r\n                        </div>\r\n                        <div class=\"text-[11px] text-gray-600 mt-0.5\">شهر <b x-text=\"myDue.month + '/' + myDue.year\"></b> — كل قراءة تُحدّث تلقائياً الهدف والخطة الاستراتيجية 📈</div>\r\n                      </div>\r\n                      <div class=\"flex items-center gap-2\">\r\n                        <button @click=\"openBulkImport()\" class=\"text-xs bg-violet-50 hover:bg-violet-100 border border-violet-200 text-violet-700 rounded px-2 py-1 whitespace-nowrap\">📋 لصق CSV</button>\r\n                        <button @click=\"goToResource('myKpi')\" class=\"text-xs text-violet-600 hover:underline whitespace-nowrap\">عرض تفصيلي ←</button>\r\n                      </div>\r\n                    </div>\r\n                    <ul class=\"divide-y\">\r\n                      <template x-for=\"k in myDue.pending.slice(0, 6)\" :key=\"k.id\">\r\n                        <li class=\"py-2\">\r\n                          <div class=\"flex items-center gap-2 flex-wrap\">\r\n                            <div class=\"flex-1 min-w-0\">\r\n                              <div class=\"flex items-center gap-1 flex-wrap\">\r\n                                <span class=\"font-mono text-[10px] text-gray-500\" x-text=\"k.code\"></span>\r\n                                <span class=\"text-[10px] px-1.5 py-0.5 rounded bg-slate-100 text-slate-600\"\r\n                                      x-text=\"k.kind === 'objective' ? 'هدف' : 'نشاط'\"></span>\r\n                                <span class=\"text-[10px] text-gray-500\" x-text=\"'مستهدف: ' + (k.targetValue ?? '—') + ' ' + (k.unit || '')\"></span>\r\n                              </div>\r\n                              <div class=\"text-sm font-medium truncate mt-0.5\" x-text=\"k.title\"></div>\r\n                              <template x-if=\"k.goalTitle\">\r\n                                <div class=\"text-[10px] text-violet-700 mt-0.5 truncate\">🎯 ينعكس على: <span x-text=\"k.goalTitle\"></span></div>\r\n                              </template>\r\n                              <!-- شريط تقدّم حيّ: يعكس currentProgress أو newProgress بعد الحفظ -->\r\n                              <div class=\"mt-1 flex items-center gap-2\">\r\n                                <div class=\"flex-1 h-1.5 bg-gray-200 rounded-full overflow-hidden\">\r\n                                  <div class=\"h-full transition-all duration-500\"\r\n                                       :class=\"{\r\n                                         'bg-red-500':    ((_draftFor(k).lastImpact?.newProgress ?? k.currentProgress ?? 0) < 50),\r\n                                         'bg-yellow-500': ((_draftFor(k).lastImpact?.newProgress ?? k.currentProgress ?? 0) >= 50 && (_draftFor(k).lastImpact?.newProgress ?? k.currentProgress ?? 0) < 80),\r\n                                         'bg-green-500':  ((_draftFor(k).lastImpact?.newProgress ?? k.currentProgress ?? 0) >= 80)\r\n                                       }\"\r\n                                       :style=\"'width:' + Math.max(2, Math.min(100, (_draftFor(k).lastImpact?.newProgress ?? k.currentProgress ?? 0))) + '%'\"></div>\r\n                                </div>\r\n                                <span class=\"text-[10px] text-gray-600 tabular-nums font-mono\"\r\n                                      x-text=\"(_draftFor(k).lastImpact?.newProgress ?? k.currentProgress ?? 0) + '%'\"></span>\r\n                              </div>\r\n                            </div>\r\n                            <div class=\"flex items-center gap-1 whitespace-nowrap\">\r\n                              <input type=\"number\" step=\"any\"\r\n                                     :placeholder=\"'القيمة الفعلية (' + (k.unit || 'رقم') + ')'\"\r\n                                     x-model=\"_draftFor(k).actualValue\"\r\n                                     @keydown.enter=\"quickSaveKpi(k)\"\r\n                                     class=\"w-32 px-2 py-1 text-sm border rounded focus:outline-none focus:ring-2 focus:ring-violet-400\">\r\n                              <template x-if=\"k.kind === 'activity'\">\r\n                                <input type=\"number\" step=\"any\" placeholder=\"المصروف (اختياري)\"\r\n                                       x-model=\"_draftFor(k).spent\"\r\n                                       class=\"w-28 px-2 py-1 text-sm border rounded focus:outline-none focus:ring-2 focus:ring-violet-400\">\r\n                              </template>\r\n                              <button type=\"button\"\r\n                                      @click=\"quickSaveKpi(k)\"\r\n                                      :disabled=\"_draftFor(k).busy\"\r\n                                      class=\"text-xs bg-violet-600 hover:bg-violet-700 disabled:opacity-50 text-white rounded px-3 py-1.5 whitespace-nowrap\">\r\n                                <span x-show=\"!_draftFor(k).busy\">💾 حفظ</span>\r\n                                <span x-show=\"_draftFor(k).busy\">⏳ جارٍ…</span>\r\n                              </button>\r\n                            </div>\r\n                          </div>\r\n                          <!-- حقول الانحراف: مطلوبة من الخادم عند النسبة < 80% -->\r\n                          <div class=\"mt-1 grid grid-cols-2 gap-1\">\r\n                            <input type=\"text\" x-model=\"_draftFor(k).deviationReason\"\r\n                                   placeholder=\"سبب الانحراف (إذا < 80%)\"\r\n                                   class=\"px-2 py-0.5 text-[10px] border border-amber-200 rounded text-gray-700 placeholder-gray-400 focus:outline-none focus:ring-1 focus:ring-amber-300\">\r\n                            <input type=\"text\" x-model=\"_draftFor(k).actionNote\"\r\n                                   placeholder=\"إجراء تصحيحي (إذا < 60%)\"\r\n                                   class=\"px-2 py-0.5 text-[10px] border border-red-200 rounded text-gray-700 placeholder-gray-400 focus:outline-none focus:ring-1 focus:ring-red-300\">\r\n                          </div>\r\n                          <!-- Impact feedback: بعد الحفظ، أظهر التغيّر في progress + Undo خلال 10 ثوانٍ -->\r\n                          <template x-if=\"_draftFor(k).lastImpact\">\r\n                            <div class=\"mt-2 text-xs bg-green-50 border border-green-200 text-green-900 rounded px-2 py-1 flex items-center gap-2 flex-wrap\">\r\n                              <span>✅ progress من</span>\r\n                              <b x-text=\"(_draftFor(k).lastImpact.prevProgress ?? 0) + '%'\"></b>\r\n                              <span>→</span>\r\n                              <b x-text=\"_draftFor(k).lastImpact.newProgress + '%'\"></b>\r\n                              <span class=\"text-[11px] opacity-75\">\r\n                                (<span x-text=\"(_draftFor(k).lastImpact.delta >= 0 ? '+' : '') + _draftFor(k).lastImpact.delta\"></span>)\r\n                              </span>\r\n                              <span class=\"text-[11px] opacity-75\" x-text=\"_draftFor(k).lastImpact.ragMessage\"></span>\r\n                              <template x-if=\"canUndo(k)\">\r\n                                <button type=\"button\"\r\n                                        @click=\"undoLastKpi(k)\"\r\n                                        :disabled=\"_draftFor(k).busy\"\r\n                                        class=\"ml-auto text-[11px] bg-white border border-amber-300 text-amber-800 hover:bg-amber-50 rounded px-2 py-0.5 disabled:opacity-50\">\r\n                                  ↩️ تراجع (<span x-text=\"undoRemainingSec(k)\"></span>ث)\r\n                                </button>\r\n                              </template>\r\n                            </div>\r\n                          </template>\r\n                        </li>\r\n                      </template>\r\n                    </ul>\r\n                    <template x-if=\"(myDue.pending || []).length > 6\">\r\n                      <div class=\"mt-2 text-center text-[11px] text-gray-500\">\r\n                        يوجد <b x-text=\"myDue.pending.length - 6\"></b> قراءات أخرى — <button @click=\"goToResource('myKpi')\" class=\"text-violet-700 hover:underline\">عرضها كلّها</button>\r\n                      </div>\r\n                    </template>\r\n                  </div>\r\n                </template>\r\n\r\n                <!-- EXEC summary (Top management only) -->\r\n                <template x-if=\"myWork.viewMode==='EXEC' && myWork.exec\">\r\n                  <details class=\"bg-white border rounded-xl mb-4 overflow-hidden\">\r\n                    <summary class=\"cursor-pointer px-4 py-3 text-sm font-bold text-slate-700 bg-slate-50 hover:bg-slate-100 list-none flex items-center justify-between\">\r\n                      <span>الصورة الرقمية التفصيلية</span>\r\n                      <span class=\"text-[11px] text-slate-500 font-normal\">افتحها عند الحاجة فقط</span>\r\n                    </summary>\r\n                    <div class=\"p-4\">\r\n                    <div class=\"grid grid-cols-2 md:grid-cols-5 gap-3\">\r\n                      <div class=\"bg-indigo-50 rounded p-3 text-center\">\r\n                        <div class=\"text-2xl font-bold text-indigo-700\" x-text=\"myWork.exec.objectives?.total || 0\"></div>\r\n                        <div class=\"text-xs text-gray-600\">إجمالي الأهداف</div>\r\n                      </div>\r\n                      <div class=\"bg-rose-50 rounded p-3 text-center\">\r\n                        <div class=\"text-2xl font-bold text-rose-700\" x-text=\"myWork.exec.risks?.critical || 0\"></div>\r\n                        <div class=\"text-xs text-gray-600\">مخاطر حرجة/مرتفعة</div>\r\n                      </div>\r\n                      <div class=\"bg-amber-50 rounded p-3 text-center\">\r\n                        <div class=\"text-2xl font-bold text-amber-700\" x-text=\"myWork.exec.complaints?.open || 0\"></div>\r\n                        <div class=\"text-xs text-gray-600\">شكاوى مفتوحة</div>\r\n                      </div>\r\n                      <div class=\"bg-orange-50 rounded p-3 text-center\">\r\n                        <div class=\"text-2xl font-bold text-orange-700\" x-text=\"myWork.exec.ncrs?.open || 0\"></div>\r\n                        <div class=\"text-xs text-gray-600\">NCR مفتوحة</div>\r\n                      </div>\r\n                      <div class=\"bg-emerald-50 rounded p-3 text-center\">\r\n                        <div class=\"text-2xl font-bold text-emerald-700\" x-text=\"myWork.exec.documents?.published || 0\"></div>\r\n                        <div class=\"text-xs text-gray-600\">وثائق منشورة</div>\r\n                      </div>\r\n                    </div>\r\n                    <!-- مؤشرات الامتثال — مهام المتابعة وملاحظات التدقيق -->\r\n                    <div class=\"grid grid-cols-2 md:grid-cols-4 gap-3 mt-3\">\r\n                      <div class=\"bg-violet-50 rounded p-3 text-center\">\r\n                        <div class=\"text-2xl font-bold text-violet-700\" x-text=\"myWork.exec.followUpTasks?.pending || 0\"></div>\r\n                        <div class=\"text-xs text-gray-600\">مهام متابعة معلّقة</div>\r\n                      </div>\r\n                      <div class=\"bg-red-50 rounded p-3 text-center\">\r\n                        <div class=\"text-2xl font-bold text-red-700\" x-text=\"myWork.exec.followUpTasks?.overdue || 0\"></div>\r\n                        <div class=\"text-xs text-gray-600\">مهام متأخرة</div>\r\n                      </div>\r\n                      <div class=\"bg-sky-50 rounded p-3 text-center\">\r\n                        <div class=\"text-2xl font-bold text-sky-700\" x-text=\"myWork.exec.auditFindings?.open || 0\"></div>\r\n                        <div class=\"text-xs text-gray-600\">ملاحظات تدقيق مفتوحة</div>\r\n                      </div>\r\n                      <div class=\"bg-pink-50 rounded p-3 text-center\" title=\"MAJOR_NC غير مغلقة — عدم مطابقات رئيسية تحتاج معالجة\">\r\n                        <div class=\"text-2xl font-bold text-pink-700\" x-text=\"myWork.exec.auditFindings?.critical || 0\"></div>\r\n                        <div class=\"text-xs text-gray-600\">MAJOR_NC مفتوحة</div>\r\n                      </div>\r\n                    </div>\r\n                    <template x-if=\"myWork.exec.mgmtReview\">\r\n                      <div class=\"mt-3 text-xs text-gray-600 bg-gray-50 rounded p-2\">\r\n                        🗓️ آخر مراجعة إدارية: <b x-text=\"myWork.exec.mgmtReview.meetingDate ? new Date(myWork.exec.mgmtReview.meetingDate).toLocaleDateString('ar-SA') : '—'\"></b>\r\n                        · الحالة: <span x-text=\"myWork.exec.mgmtReview.status\"></span>\r\n                      </div>\r\n                    </template>\r\n                    </div>\r\n                  </details>\r\n                </template>\r\n\r\n                <!-- QUALITY block (quality manager + committee member) -->\r\n                <template x-if=\"myWork.viewMode==='QUALITY' && myWork.quality\">\r\n                  <details class=\"bg-white border rounded-xl mb-4 overflow-hidden\">\r\n                    <summary class=\"cursor-pointer px-4 py-3 text-sm font-bold text-slate-700 bg-slate-50 hover:bg-slate-100 list-none flex items-center justify-between\">\r\n                      <span>لوحة الجودة التفصيلية</span>\r\n                      <span class=\"text-[11px] text-slate-500 font-normal\">للمراجعة الأسبوعية والشهرية</span>\r\n                    </summary>\r\n                    <div class=\"p-4\">\r\n                    <div class=\"flex items-center justify-between mb-3\">\r\n                      <div class=\"font-bold text-rose-800 text-sm\">🛡️ لوحة الجودة الشاملة</div>\r\n                      <button @click=\"openQualityDashboard()\"\r\n                        class=\"text-xs bg-rose-600 hover:bg-rose-700 text-white px-3 py-1.5 rounded-lg flex items-center gap-1\">\r\n                        📊 <span>التحليلات</span>\r\n                      </button>\r\n                    </div>\r\n                    <!-- Row 1: NCR metrics -->\r\n                    <div class=\"grid grid-cols-2 md:grid-cols-4 gap-3 mb-3\">\r\n                      <div class=\"bg-orange-50 rounded p-3 text-center\">\r\n                        <div class=\"text-2xl font-bold text-orange-700\" x-text=\"myWork.quality.ncr?.open || 0\"></div>\r\n                        <div class=\"text-xs text-gray-600\">NCR مفتوحة</div>\r\n                      </div>\r\n                      <div class=\"bg-red-50 rounded p-3 text-center\">\r\n                        <div class=\"text-2xl font-bold text-red-700\" x-text=\"myWork.quality.ncr?.overdue || 0\"></div>\r\n                        <div class=\"text-xs text-gray-600\">NCR متأخرة</div>\r\n                      </div>\r\n                      <div class=\"bg-amber-50 rounded p-3 text-center\">\r\n                        <div class=\"text-2xl font-bold text-amber-700\" x-text=\"myWork.quality.ncr?.pendingReview || 0\"></div>\r\n                        <div class=\"text-xs text-gray-600\">بانتظار المراجعة</div>\r\n                      </div>\r\n                      <div class=\"bg-violet-50 rounded p-3 text-center\">\r\n                        <div class=\"text-2xl font-bold text-violet-700\" x-text=\"myWork.quality.ncr?.pendingApproval || 0\"></div>\r\n                        <div class=\"text-xs text-gray-600\">بانتظار الاعتماد</div>\r\n                      </div>\r\n                    </div>\r\n                    <!-- Row 2: Complaints + Audit Findings + Follow-up Tasks -->\r\n                    <div class=\"grid grid-cols-2 md:grid-cols-4 gap-3\">\r\n                      <div class=\"bg-rose-50 rounded p-3 text-center\">\r\n                        <div class=\"text-2xl font-bold text-rose-700\" x-text=\"myWork.quality.complaints?.breached || 0\"></div>\r\n                        <div class=\"text-xs text-gray-600\">شكاوى متجاوزة SLA</div>\r\n                      </div>\r\n                      <div class=\"bg-sky-50 rounded p-3 text-center\">\r\n                        <div class=\"text-2xl font-bold text-sky-700\" x-text=\"myWork.quality.auditFindings?.open || 0\"></div>\r\n                        <div class=\"text-xs text-gray-600\">ملاحظات تدقيق مفتوحة</div>\r\n                      </div>\r\n                      <div class=\"bg-pink-50 rounded p-3 text-center\" title=\"MAJOR_NC غير مغلقة\">\r\n                        <div class=\"text-2xl font-bold text-pink-700\" x-text=\"myWork.quality.auditFindings?.critical || 0\"></div>\r\n                        <div class=\"text-xs text-gray-600\">MAJOR_NC مفتوحة</div>\r\n                      </div>\r\n                      <div class=\"bg-yellow-50 rounded p-3 text-center\">\r\n                        <div class=\"text-2xl font-bold text-yellow-700\" x-text=\"myWork.quality.followUpTasks?.overdue || 0\"></div>\r\n                        <div class=\"text-xs text-gray-600\">مهام متابعة متأخرة</div>\r\n                      </div>\r\n                    </div>\r\n                    </div>\r\n                  </details>\r\n                </template>\r\n\r\n                <!-- DEPT block (department manager only) -->\r\n                <template x-if=\"myWork.viewMode==='DEPT' && myWork.dept\">\r\n                  <details class=\"bg-white border rounded-xl mb-4 overflow-hidden\">\r\n                    <summary class=\"cursor-pointer px-4 py-3 text-sm font-bold text-slate-700 bg-slate-50 hover:bg-slate-100 list-none flex items-center justify-between\">\r\n                      <span>لوحة القسم التفصيلية</span>\r\n                      <span class=\"text-[11px] text-slate-500 font-normal\">افتحها عند المراجعة مع الفريق</span>\r\n                    </summary>\r\n                    <div class=\"p-4\">\r\n                    <div class=\"flex items-center justify-between mb-3\">\r\n                      <div>\r\n                        <div class=\"font-bold text-teal-800 text-sm\">👥 قسم: <span x-text=\"myWork.dept.department?.name || '—'\"></span></div>\r\n                        <div class=\"text-xs text-gray-500\">عدد أعضاء الفريق: <b x-text=\"myWork.dept.teamSize\"></b></div>\r\n                      </div>\r\n                      <button @click=\"openDeptDashboard()\"\r\n                        class=\"text-xs bg-teal-600 hover:bg-teal-700 text-white px-3 py-1.5 rounded-lg flex items-center gap-1\">\r\n                        📊 <span>لوحة القسم</span>\r\n                      </button>\r\n                    </div>\r\n                    <div class=\"grid grid-cols-3 gap-3 text-center\">\r\n                      <div class=\"bg-orange-50 rounded p-3\">\r\n                        <div class=\"text-2xl font-bold text-orange-700\" x-text=\"myWork.dept.ncrAssigned?.length || 0\"></div>\r\n                        <div class=\"text-xs text-gray-600\">NCR في فريقي</div>\r\n                      </div>\r\n                      <div class=\"bg-rose-50 rounded p-3\">\r\n                        <div class=\"text-2xl font-bold text-rose-700\" x-text=\"myWork.dept.complaintsAssigned?.length || 0\"></div>\r\n                        <div class=\"text-xs text-gray-600\">شكاوى في فريقي</div>\r\n                      </div>\r\n                      <div class=\"bg-violet-50 rounded p-3\">\r\n                        <div class=\"text-2xl font-bold text-violet-700\" x-text=\"myWork.dept.kpiPendingCount || 0\"></div>\r\n                        <div class=\"text-xs text-gray-600\">قراءات KPI ناقصة</div>\r\n                      </div>\r\n                    </div>\r\n                    <template x-if=\"(myWork.dept.ncrAssigned||[]).length\">\r\n                      <div class=\"mt-3\">\r\n                        <div class=\"text-xs font-bold text-gray-700 mb-1\">NCR الفريق:</div>\r\n                        <ul class=\"divide-y text-sm border rounded\">\r\n                          <template x-for=\"n in myWork.dept.ncrAssigned.slice(0,6)\" :key=\"n.id\">\r\n                            <li class=\"p-2 flex justify-between items-center gap-2 hover:bg-gray-50\">\r\n                              <div class=\"flex-1 min-w-0\">\r\n                                <span class=\"font-mono text-xs text-gray-500 ml-2\" x-text=\"n.code\"></span>\r\n                                <span :class=\"'text-xs px-1.5 py-0.5 rounded ' + severityBadgeClass(n.severity)\" x-text=\"n.severity\"></span>\r\n                                <span class=\"truncate mr-2\" x-text=\"n.title\"></span>\r\n                              </div>\r\n                              <button @click=\"goToResource('ncr')\" class=\"text-xs text-blue-600 hover:underline\">فتح ←</button>\r\n                            </li>\r\n                          </template>\r\n                        </ul>\r\n                      </div>\r\n                    </template>\r\n                    </div>\r\n                  </details>\r\n                </template>\r\n\r\n                <!-- Empty state -->\r\n                <template x-if=\"!myWork.summary.totalActions\">\r\n                  <div class=\"bg-green-50 border border-green-200 text-green-800 rounded-xl p-6 text-center\">\r\n                    <div class=\"text-4xl mb-2\">🎉</div>\r\n                    <div class=\"font-bold text-lg\">لا توجد مهام معلّقة عليك الآن</div>\r\n                    <div class=\"text-sm text-green-700 mt-1\">يمكنك تصفح الوحدات من القائمة الجانبية.</div>\r\n                  </div>\r\n                </template>\r\n\r\n                <details class=\"bg-white border rounded-xl mb-4 overflow-hidden\">\r\n                  <summary class=\"cursor-pointer px-4 py-3 text-sm font-bold text-slate-700 bg-slate-50 hover:bg-slate-100 list-none flex items-center justify-between\">\r\n                    <span>تفاصيل العناصر حسب الوحدة</span>\r\n                    <span class=\"text-[11px] text-slate-500 font-normal\">افتحها إذا أردت مراجعة السجلات واحداً واحداً</span>\r\n                  </summary>\r\n                  <div class=\"grid md:grid-cols-2 gap-4 p-4\">\r\n                  <!-- KPI -->\r\n                  <template x-if=\"myWork.kpi && myWork.kpi.pending > 0\">\r\n                    <div class=\"bg-white border rounded-xl overflow-hidden\">\r\n                      <div class=\"bg-violet-50 px-4 py-2 flex justify-between items-center\">\r\n                        <div class=\"font-bold text-violet-800\">🎯 قراءات KPI المطلوبة</div>\r\n                        <span class=\"text-xs text-gray-500\" x-text=\"myWork.kpi.month + '/' + myWork.kpi.year\"></span>\r\n                      </div>\r\n                      <div class=\"p-4 flex items-center gap-4\">\r\n                        <div class=\"text-4xl font-bold\" :class=\"myWork.kpi.pending ? 'text-red-600' : 'text-green-600'\"\r\n                             x-text=\"myWork.kpi.pending\"></div>\r\n                        <div class=\"flex-1\">\r\n                          <div class=\"text-sm\">معلّق من أصل <b x-text=\"myWork.kpi.total\"></b></div>\r\n                          <div class=\"text-xs text-gray-500\">تم إدخال <b x-text=\"myWork.kpi.entered\"></b></div>\r\n                        </div>\r\n                        <button @click=\"goToResource('myKpi')\" class=\"bg-violet-600 hover:bg-violet-700 text-white rounded px-3 py-1.5 text-sm\">فتح ←</button>\r\n                      </div>\r\n                    </div>\r\n                  </template>\r\n\r\n                  <!-- NCR assigned to me -->\r\n                  <div class=\"bg-white border rounded-xl overflow-hidden\" x-show=\"myWork.ncr.assigned?.length\">\r\n                    <div class=\"bg-orange-50 px-4 py-2 font-bold text-orange-800\">🔧 عدم المطابقة المسندة لي (<span x-text=\"myWork.ncr.assigned.length\"></span>)</div>\r\n                    <ul class=\"divide-y text-sm\">\r\n                      <template x-for=\"n in myWork.ncr.assigned\" :key=\"n.id\">\r\n                        <li class=\"p-3 flex justify-between items-center gap-2 hover:bg-gray-50\">\r\n                          <div class=\"flex-1 min-w-0\">\r\n                            <div class=\"flex items-center gap-2 flex-wrap\">\r\n                              <span class=\"font-mono text-xs text-gray-500\" x-text=\"n.code\"></span>\r\n                              <span :class=\"'text-xs px-1.5 py-0.5 rounded ' + severityBadgeClass(n.severity)\" x-text=\"n.severity\"></span>\r\n                              <span class=\"text-xs text-gray-500\" x-text=\"n.status\"></span>\r\n                            </div>\r\n                            <div class=\"truncate\" x-text=\"n.title\"></div>\r\n                          </div>\r\n                          <button @click=\"goToResource('ncr')\" class=\"text-xs text-blue-600 hover:underline whitespace-nowrap\">فتح ←</button>\r\n                        </li>\r\n                      </template>\r\n                    </ul>\r\n                  </div>\r\n\r\n                  <!-- Complaints assigned to me -->\r\n                  <div class=\"bg-white border rounded-xl overflow-hidden\" x-show=\"myWork.complaints.assigned?.length\">\r\n                    <div class=\"bg-rose-50 px-4 py-2 font-bold text-rose-800\">💬 الشكاوى المسندة لي (<span x-text=\"myWork.complaints.assigned.length\"></span>)</div>\r\n                    <ul class=\"divide-y text-sm\">\r\n                      <template x-for=\"c in myWork.complaints.assigned\" :key=\"c.id\">\r\n                        <li class=\"p-3 flex justify-between items-center gap-2 hover:bg-gray-50\">\r\n                          <div class=\"flex-1 min-w-0\">\r\n                            <div class=\"flex items-center gap-2 flex-wrap\">\r\n                              <span class=\"font-mono text-xs text-gray-500\" x-text=\"c.code\"></span>\r\n                              <span :class=\"'text-xs px-1.5 py-0.5 rounded ' + severityBadgeClass(c.severity)\" x-text=\"c.severity\"></span>\r\n                            </div>\r\n                            <div class=\"truncate\" x-text=\"c.subject\"></div>\r\n                          </div>\r\n                          <button @click=\"goToResource('complaints')\" class=\"text-xs text-blue-600 hover:underline whitespace-nowrap\">فتح ←</button>\r\n                        </li>\r\n                      </template>\r\n                    </ul>\r\n                  </div>\r\n\r\n                  <!-- Workflow reviews/approvals (privileged) -->\r\n                  <div class=\"bg-white border rounded-xl overflow-hidden\"\r\n                       x-show=\"myWork.ncr.pendingReview?.length || myWork.ncr.pendingApproval?.length\">\r\n                    <div class=\"bg-sky-50 px-4 py-2 font-bold text-sky-800\"\r\n                         x-text=\"(isGuided() ? '📋 بلاغات جودة بانتظار المراجعة/الاعتماد' : '📋 NCR بانتظار المراجعة/الاعتماد')\"></div>\r\n                    <ul class=\"divide-y text-sm\">\r\n                      <template x-for=\"n in [...(myWork.ncr.pendingReview||[]), ...(myWork.ncr.pendingApproval||[])]\" :key=\"n.id\">\r\n                        <li class=\"p-3 flex flex-wrap justify-between items-center gap-2 hover:bg-gray-50\">\r\n                          <div class=\"flex-1 min-w-0\">\r\n                            <span class=\"font-mono text-xs text-gray-500 ml-2\" x-text=\"n.code\"></span>\r\n                            <span class=\"text-[10px] px-1.5 py-0.5 rounded\" :class=\"workflowStateClass(n.workflowState)\" x-text=\"workflowStateLabel(n.workflowState)\"></span>\r\n                            <span class=\"truncate mr-1\" x-text=\"n.title\"></span>\r\n                          </div>\r\n                          <div class=\"flex items-center gap-1 whitespace-nowrap\">\r\n                            <!-- Inbox inline actions -->\r\n                            <template x-if=\"canInbox(n, 'review')\">\r\n                              <button type=\"button\" @click=\"inboxReview(n, 'ncr')\" :disabled=\"inboxBusy(n, 'review')\"\r\n                                      class=\"text-[11px] bg-sky-600 hover:bg-sky-700 text-white rounded px-2 py-1 disabled:opacity-50\"\r\n                                      title=\"استلام للمراجعة دون مغادرة الصفحة\">🔍 استلم للمراجعة</button>\r\n                            </template>\r\n                            <template x-if=\"canInbox(n, 'approve')\">\r\n                              <button type=\"button\" @click=\"inboxApprove(n, 'ncr')\" :disabled=\"inboxBusy(n, 'approve')\"\r\n                                      class=\"text-[11px] bg-green-600 hover:bg-green-700 text-white rounded px-2 py-1 disabled:opacity-50\"\r\n                                      title=\"اعتماد السجل\">✅ اعتمد</button>\r\n                            </template>\r\n                            <template x-if=\"canInbox(n, 'reject')\">\r\n                              <button type=\"button\" @click=\"inboxReject(n, 'ncr')\" :disabled=\"inboxBusy(n, 'reject')\"\r\n                                      class=\"text-[11px] bg-red-600 hover:bg-red-700 text-white rounded px-2 py-1 disabled:opacity-50\"\r\n                                      title=\"رفض السجل\">✖ ارفض</button>\r\n                            </template>\r\n                            <button @click=\"goToResource('ncr')\" class=\"text-xs text-blue-600 hover:underline\">فتح ←</button>\r\n                          </div>\r\n                        </li>\r\n                      </template>\r\n                    </ul>\r\n                  </div>\r\n\r\n                  <!-- Risks/SupplierEvals workflow -->\r\n                  <div class=\"bg-white border rounded-xl overflow-hidden\"\r\n                       x-show=\"myWork.workflow.risksPendingReview?.length\">\r\n                    <div class=\"bg-amber-50 px-4 py-2 font-bold text-amber-800\">⚠️ مخاطر بانتظار المراجعة</div>\r\n                    <ul class=\"divide-y text-sm\">\r\n                      <template x-for=\"r in myWork.workflow.risksPendingReview\" :key=\"r.id\">\r\n                        <li class=\"p-3 flex flex-wrap justify-between items-center gap-2 hover:bg-gray-50\">\r\n                          <div class=\"flex-1 min-w-0\">\r\n                            <span class=\"font-mono text-xs text-gray-500 ml-2\" x-text=\"r.code\"></span>\r\n                            <span class=\"text-[10px] px-1.5 py-0.5 rounded\" :class=\"workflowStateClass(r.workflowState)\" x-text=\"workflowStateLabel(r.workflowState)\"></span>\r\n                            <span class=\"truncate mr-1\" x-text=\"r.title\"></span>\r\n                          </div>\r\n                          <div class=\"flex items-center gap-1 whitespace-nowrap\">\r\n                            <template x-if=\"canInbox(r, 'review')\">\r\n                              <button type=\"button\" @click=\"inboxReview(r, 'risks')\" :disabled=\"inboxBusy(r, 'review')\"\r\n                                      class=\"text-[11px] bg-sky-600 hover:bg-sky-700 text-white rounded px-2 py-1 disabled:opacity-50\">🔍 استلم</button>\r\n                            </template>\r\n                            <template x-if=\"canInbox(r, 'approve')\">\r\n                              <button type=\"button\" @click=\"inboxApprove(r, 'risks')\" :disabled=\"inboxBusy(r, 'approve')\"\r\n                                      class=\"text-[11px] bg-green-600 hover:bg-green-700 text-white rounded px-2 py-1 disabled:opacity-50\">✅ اعتمد</button>\r\n                            </template>\r\n                            <template x-if=\"canInbox(r, 'reject')\">\r\n                              <button type=\"button\" @click=\"inboxReject(r, 'risks')\" :disabled=\"inboxBusy(r, 'reject')\"\r\n                                      class=\"text-[11px] bg-red-600 hover:bg-red-700 text-white rounded px-2 py-1 disabled:opacity-50\">✖ ارفض</button>\r\n                            </template>\r\n                            <button @click=\"goToResource('risks')\" class=\"text-xs text-blue-600 hover:underline\">فتح ←</button>\r\n                          </div>\r\n                        </li>\r\n                      </template>\r\n                    </ul>\r\n                  </div>\r\n\r\n                  <div class=\"bg-white border rounded-xl overflow-hidden\"\r\n                       x-show=\"myWork.workflow.supplierEvalsPendingReview?.length\">\r\n                    <div class=\"bg-emerald-50 px-4 py-2 font-bold text-emerald-800\">🏭 تقييمات موردين بانتظار المراجعة</div>\r\n                    <ul class=\"divide-y text-sm\">\r\n                      <template x-for=\"e in myWork.workflow.supplierEvalsPendingReview\" :key=\"e.id\">\r\n                        <li class=\"p-3 flex justify-between items-center gap-2 hover:bg-gray-50\">\r\n                          <div class=\"flex-1 min-w-0\">\r\n                            <span class=\"font-mono text-xs text-gray-500 ml-2\" x-text=\"e.code\"></span>\r\n                            <span class=\"truncate\" x-text=\"e.supplier?.name || '—'\"></span>\r\n                          </div>\r\n                          <button @click=\"goToResource('suppliers')\" class=\"text-xs text-blue-600 hover:underline\">فتح ←</button>\r\n                        </li>\r\n                      </template>\r\n                    </ul>\r\n                  </div>\r\n\r\n                  <!-- SLA breached complaints (privileged) -->\r\n                  <div class=\"bg-white border rounded-xl overflow-hidden\"\r\n                       x-show=\"myWork.complaints.breached?.length\">\r\n                    <div class=\"bg-red-50 px-4 py-2 font-bold text-red-800\">⛔ شكاوى تجاوزت SLA</div>\r\n                    <ul class=\"divide-y text-sm\">\r\n                      <template x-for=\"c in myWork.complaints.breached\" :key=\"c.id\">\r\n                        <li class=\"p-3 flex justify-between items-center gap-2 hover:bg-gray-50\">\r\n                          <div class=\"flex-1 min-w-0\">\r\n                            <span class=\"font-mono text-xs text-gray-500 ml-2\" x-text=\"c.code\"></span>\r\n                            <span class=\"truncate\" x-text=\"c.subject\"></span>\r\n                            <span class=\"text-xs text-red-600 mr-2\">(عمر: <span x-text=\"c.ageDays\"></span>ي)</span>\r\n                          </div>\r\n                          <button @click=\"goToResource('slaBoard')\" class=\"text-xs text-blue-600 hover:underline\">لوحة SLA ←</button>\r\n                        </li>\r\n                      </template>\r\n                    </ul>\r\n                  </div>\r\n\r\n                  <!-- Beneficiaries due review (privileged) -->\r\n                  <div class=\"bg-white border rounded-xl overflow-hidden\"\r\n                       x-show=\"myWork.beneficiaries.dueReview?.length\">\r\n                    <div class=\"bg-cyan-50 px-4 py-2 font-bold text-cyan-800\">👥 مستفيدون يلزمهم إعادة تقييم</div>\r\n                    <ul class=\"divide-y text-sm\">\r\n                      <template x-for=\"b in myWork.beneficiaries.dueReview\" :key=\"b.id\">\r\n                        <li class=\"p-3 flex justify-between items-center gap-2 hover:bg-gray-50\">\r\n                          <div class=\"flex-1 min-w-0\">\r\n                            <span class=\"font-mono text-xs text-gray-500 ml-2\" x-text=\"b.code\"></span>\r\n                            <span class=\"truncate\" x-text=\"b.fullName\"></span>\r\n                          </div>\r\n                          <button @click=\"goToResource('beneficiaries')\" class=\"text-xs text-blue-600 hover:underline\">فتح ←</button>\r\n                        </li>\r\n                      </template>\r\n                    </ul>\r\n                  </div>\r\n                  </div>\r\n                </details>\r\n\r\n              </div>\r\n            </template>\r\n          </div>";
  function mount() {
    const host = document.getElementById('my-work-page-host');
    if (!host || host.dataset.templateMounted === '1') return;
    host.innerHTML = html;
    host.dataset.templateMounted = '1';
    if (window.Alpine?.initTree) window.Alpine.initTree(host);
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', mount, { once: true });
  } else {
    mount();
  }
})();
